368	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
369	                                           const qemu_info_t *info,
370	                                           int argc, char **argv)
371	{
372	    (void) info;
373	    for (int i = 0; i < argc; i++) {
374	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
375	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
376	            outfile_path = g_strdup(tok[1]);
377	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
378	            char *endp = NULL;
379	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
380	            if (!endp || *endp != '\0') {
381	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
382	                        tok[1]);
383	                return -1;
384	            }
385	            enter_pc_arg = (uint64_t) v;
386	            pc_mode = 1;
387	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
388	            // F14: any non-zero value enables. "1" is the canonical form
389	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
390	            // also enable -- the flag is a binary switch, not a count.
391	            char *endp = NULL;
392	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
393	            if (!endp || *endp != '\0') {
394	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
395	                        tok[1]);
396	                return -1;
397	            }
398	            drain_at_exit_mode = (v != 0);
399	        } else {
400	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
401	            return -1;
402	        }
403	    }
404	    if (!outfile_path) {
405	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
406	        return -1;
407	    }
408	    if (pc_mode) {
409	        fprintf(stderr,
410	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
411	                enter_pc_arg);
412	    }
413	    if (drain_at_exit_mode) {
414	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
415	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
416	    }
417	
418	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
419	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
420	    return 0;
421	}
